create extension if not exists postgis;
create extension if not exists pgcrypto;

create type public.shrine_deity_role as enum ('principal', 'enshrined', 'co_enshrined', 'associated');
create type public.source_type as enum ('official_site', 'shrine_association', 'government', 'publication', 'other');
create type public.digital_memento_status as enum ('disabled', 'pending_permission', 'enabled');

create table public.prefectures (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique);
create table public.municipalities (id uuid primary key default gen_random_uuid(), prefecture_id uuid not null references public.prefectures(id), name text not null, unique(prefecture_id, name));
create table public.deities (id uuid primary key default gen_random_uuid(), name text not null, reading text, aliases text[] not null default '{}', summary text, mythology text, divinity text, slug text not null unique, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.historical_figures (id uuid primary key default gen_random_uuid(), name text not null, reading text, summary text, deification_description text, slug text not null unique, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.lineages (id uuid primary key default gen_random_uuid(), name text not null unique, reading text, description text, slug text not null unique, is_published boolean not null default false);
create table public.benefits (id uuid primary key default gen_random_uuid(), name text not null unique, description text, slug text not null unique, is_published boolean not null default false);
create table public.shrines (id uuid primary key default gen_random_uuid(), name text not null, reading text, slug text not null unique, prefecture_id uuid references public.prefectures(id), municipality_id uuid references public.municipalities(id), address text, location geography(point,4326), official_url text, founding_description text, history text, name_origin text, cultural_properties text, access_info text, parking_info text, worship_hours text, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index shrines_location_index on public.shrines using gist(location);
create table public.shrine_deities (shrine_id uuid not null references public.shrines(id) on delete cascade, deity_id uuid not null references public.deities(id) on delete cascade, role public.shrine_deity_role not null default 'enshrined', display_order smallint not null default 0, primary key(shrine_id,deity_id));
create table public.shrine_figures (shrine_id uuid not null references public.shrines(id) on delete cascade, figure_id uuid not null references public.historical_figures(id) on delete cascade, description text, primary key(shrine_id,figure_id));
create table public.shrine_lineages (shrine_id uuid not null references public.shrines(id) on delete cascade, lineage_id uuid not null references public.lineages(id) on delete cascade, primary key(shrine_id,lineage_id));
create table public.shrine_benefits (shrine_id uuid not null references public.shrines(id) on delete cascade, benefit_id uuid not null references public.benefits(id) on delete cascade, description text, primary key(shrine_id,benefit_id));
create table public.sources (id uuid primary key default gen_random_uuid(), name text not null, url text, source_type public.source_type not null, last_verified_at date not null, notes text);
create table public.shrine_sources (shrine_id uuid not null references public.shrines(id) on delete cascade, source_id uuid not null references public.sources(id) on delete cascade, field_name text, primary key(shrine_id,source_id));
create table public.shrine_images (id uuid primary key default gen_random_uuid(), shrine_id uuid not null references public.shrines(id) on delete cascade, image_url text not null, alt_text text not null, source_credit text, display_order smallint not null default 0);
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now());
create table public.admin_allowlist (email text primary key, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.favorites (user_id uuid not null references auth.users(id) on delete cascade, shrine_id uuid not null references public.shrines(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,shrine_id));
create table public.visits (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, shrine_id uuid not null references public.shrines(id), visited_at timestamptz not null, recorded_location geography(point,4326), location_accuracy_meters numeric, memo text, received_physical_goshuin boolean, created_at timestamptz not null default now());
create table public.visit_photos (id uuid primary key default gen_random_uuid(), visit_id uuid not null references public.visits(id) on delete cascade, storage_path text not null, caption text, created_at timestamptz not null default now());
create table public.digital_goshuin_settings (shrine_id uuid primary key references public.shrines(id) on delete cascade, status public.digital_memento_status not null default 'pending_permission', radius_meters integer not null default 150 check(radius_meters between 25 and 1000), design_key text, updated_at timestamptz not null default now());
create table public.digital_goshuin (id uuid primary key default gen_random_uuid(), visit_id uuid not null unique references public.visits(id) on delete cascade, shrine_id uuid not null references public.shrines(id), user_id uuid not null references auth.users(id) on delete cascade, issued_at timestamptz not null default now(), verified_by_gps boolean not null default false, design_snapshot jsonb not null default '{}'::jsonb);

alter table public.prefectures enable row level security; alter table public.municipalities enable row level security; alter table public.deities enable row level security; alter table public.historical_figures enable row level security; alter table public.lineages enable row level security; alter table public.benefits enable row level security; alter table public.shrines enable row level security; alter table public.shrine_deities enable row level security; alter table public.shrine_figures enable row level security; alter table public.shrine_lineages enable row level security; alter table public.shrine_benefits enable row level security; alter table public.sources enable row level security; alter table public.shrine_sources enable row level security; alter table public.shrine_images enable row level security; alter table public.profiles enable row level security; alter table public.favorites enable row level security; alter table public.visits enable row level security; alter table public.visit_photos enable row level security; alter table public.digital_goshuin_settings enable row level security; alter table public.digital_goshuin enable row level security;
create policy "public reads published shrines" on public.shrines for select using (is_published);
create policy "public reads published deities" on public.deities for select using (is_published);
create policy "public reads published lineages" on public.lineages for select using (is_published);
create policy "public reads published benefits" on public.benefits for select using (is_published);
create policy "public reads published relations" on public.shrine_deities for select using (exists(select 1 from public.shrines where id=shrine_id and is_published));
create policy "users manage own favorites" on public.favorites for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "users manage own visits" on public.visits for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "users manage own visit photos" on public.visit_photos for all using (exists(select 1 from public.visits where id=visit_id and user_id=auth.uid())) with check (exists(select 1 from public.visits where id=visit_id and user_id=auth.uid()));
create policy "users read own digital mementos" on public.digital_goshuin for select using (auth.uid()=user_id);